import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Paper,
  Button,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  CircularProgress,
  Container,
  Chip,
  Avatar
} from '@mui/material';
import { 
  Users, 
  DollarSign, 
  Clock, 
  AlertTriangle,
  TrendingUp,
  Calendar,
  Award,
  FileText,
  Plus
} from 'lucide-react';
import { collection, getDocs } from 'firebase/firestore';
import { db } from '../../../firebase/config';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const [stats, setStats] = useState({
    totalEmployees: 0,
    activeEmployees: 0,
    pendingPayroll: 0,
    expiringLicenses: 0,
    todayAttendance: 0,
    pendingReviews: 0
  });
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    initializeAndFetchData();
  }, []);

  const initializeAndFetchData = async () => {
    try {
      // Fetch dashboard stats directly
      await fetchDashboardStats();
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load dashboard data');
    }
  };

  const fetchDashboardStats = async () => {
    try {
      // Fetch employees
      const employeesSnapshot = await getDocs(collection(db, 'employees'));
      const employees = employeesSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      
      const activeEmployees = employees.filter(emp => emp.status === 'active');
      
      // Fetch licenses expiring in next 30 days
      const thirtyDaysFromNow = new Date();
      thirtyDaysFromNow.setDate(thirtyDaysFromNow.getDate() + 30);
      
      const licensesSnapshot = await getDocs(collection(db, 'licenses'));
      const expiringLicenses = licensesSnapshot.docs.filter(doc => {
        const license = doc.data();
        const expiryDate = new Date(license.expiryDate);
        return expiryDate <= thirtyDaysFromNow && expiryDate >= new Date();
      });

      // Fetch actual payroll data
      const payrollSnapshot = await getDocs(collection(db, 'payrolls'));
      const pendingPayrolls = payrollSnapshot.docs.filter(doc => {
        const payroll = doc.data();
        return payroll.status === 'pending' || payroll.status === 'draft';
      });

      // Fetch today's attendance
      const today = new Date().toISOString().split('T')[0];
      const attendanceSnapshot = await getDocs(collection(db, 'attendance'));
      const todayAttendance = attendanceSnapshot.docs.filter(doc => {
        const attendance = doc.data();
        return attendance.date === today && attendance.status === 'present';
      });

      // Fetch pending performance reviews
      const reviewsSnapshot = await getDocs(collection(db, 'performance_reviews'));
      const pendingReviews = reviewsSnapshot.docs.filter(doc => {
        const review = doc.data();
        return review.status === 'pending' || review.status === 'draft';
      });

      setStats({
        totalEmployees: employees.length,
        activeEmployees: activeEmployees.length,
        pendingPayroll: pendingPayrolls.length,
        expiringLicenses: expiringLicenses.length,
        todayAttendance: todayAttendance.length,
        pendingReviews: pendingReviews.length
      });
    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
    } finally {
      setLoading(false);
    }
  };

  const statCards = [
    {
      title: 'Total Employees',
      value: stats.totalEmployees,
      icon: Users,
      color: '#1e40af',
      bgColor: '#dbeafe',
      link: '/hr/employees'
    },
    {
      title: 'Active Employees',
      value: stats.activeEmployees,
      icon: TrendingUp,
      color: '#059669',
      bgColor: '#dcfce7',
      link: '/hr/employees'
    },
    {
      title: 'Pending Payroll',
      value: stats.pendingPayroll,
      icon: DollarSign,
      color: '#d97706',
      bgColor: '#fef3c7',
      link: '/hr/payroll'
    },
    {
      title: 'Expiring Licenses',
      value: stats.expiringLicenses,
      icon: AlertTriangle,
      color: '#dc2626',
      bgColor: '#fee2e2',
      link: '/hr/licenses'
    },
    {
      title: 'Today Attendance',
      value: stats.todayAttendance,
      icon: Clock,
      color: '#7c3aed',
      bgColor: '#ede9fe',
      link: '/hr/attendance'
    },
    {
      title: 'Pending Reviews',
      value: stats.pendingReviews,
      icon: FileText,
      color: '#4338ca',
      bgColor: '#e0e7ff',
      link: '/hr/performance'
    }
  ];

  const quickActions = [
    { title: 'Add New Employee', link: '/hr/employees/new', icon: Plus },
    { title: 'Process Payroll', link: '/hr/payroll', icon: DollarSign },
    { title: 'Mark Attendance', link: '/hr/attendance', icon: Clock },
    { title: 'License Tracking', link: '/hr/licenses', icon: Award }
  ];

  if (loading) {
    return (
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'center', 
        alignItems: 'center', 
        height: '400px' 
      }}>
        <CircularProgress size={60} sx={{ color: '#1e40af' }} />
      </Box>
    );
  }

  return (
    <Container maxWidth="xl" sx={{ py: 3 }}>
      {/* Header */}
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        mb: 4 
      }}>
        <Typography 
          variant="h4" 
          sx={{ 
            fontWeight: 'bold', 
            color: '#1e3a8a',
            letterSpacing: '0.5px'
          }}
        >
          HR Dashboard
        </Typography>
        <Button
          variant="contained"
          startIcon={<Plus size={20} />}
          onClick={() => navigate('/hr/employees/new')}
          sx={{ 
            px: 3, 
            py: 1.5, 
            borderRadius: 2,
            backgroundColor: '#1565c0',
            fontWeight: 'bold',
            textTransform: 'none',
            '&:hover': { backgroundColor: '#0d47a1' }
          }}
        >
          Add New Employee
        </Button>
      </Box>

      {/* Stats Grid */}
      <Grid container spacing={3}>
        {statCards.map((stat, index) => {
          const Icon = stat.icon;
          return (
            <Grid item xs={12} sm={6} md={4} lg={2} key={index}>
              <Card
                sx={{
                  borderRadius: '16px',
                  border: '1px solid #f0f0f0',
                  cursor: 'pointer',
                  transition: 'all 0.2s ease-in-out',
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: '0 10px 25px rgba(0,0,0,0.15)',
                    borderColor: stat.color
                  }
                }}
                onClick={() => {
                  navigate(stat.link);
                }}
              >
                <CardContent sx={{ p: 3, flex: 1 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
                    <Avatar
                      sx={{
                        backgroundColor: stat.bgColor,
                        width: 48,
                        height: 48
                      }}
                    >
                      <Icon size={24} color={stat.color} />
                    </Avatar>
                    <Chip
                      label="Live"
                      size="small"
                      sx={{
                        backgroundColor: '#10b981',
                        color: 'white',
                        fontWeight: 'bold',
                        fontSize: '10px',
                        height: 20
                      }}
                    />
                  </Box>
                  <Typography
                    variant="h3"
                    sx={{
                      fontWeight: 'bold',
                      color: '#1f2937',
                      mb: 1,
                      fontSize: '28px'
                    }}
                  >
                    {stat.value}
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      color: '#6b7280',
                      fontWeight: '500',
                      fontSize: '14px'
                    }}
                  >
                    {stat.title}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>

      {/* Quick Actions */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: '16px',
          border: '1px solid #f0f0f0',
          mb: 4,
          boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
        }}
      >
        <Box sx={{ p: 3 }}>
          <Typography
            variant="h6"
            sx={{
              fontWeight: 'bold',
              color: '#1f2937',
              mb: 3,
              fontSize: '18px'
            }}
          >
            Quick Actions
          </Typography>
          <Grid container spacing={2}>
            {quickActions.map((action, index) => {
              const Icon = action.icon;
              return (
                <Grid item xs={12} sm={6} md={3} key={index}>
                  <Card
                    sx={{
                      borderRadius: '12px',
                      border: '1px solid #e5e7eb',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease-in-out',
                      height: '100%',
                      display: 'flex',
                      flexDirection: 'column',
                      '&:hover': {
                        backgroundColor: '#f8fafc',
                        borderColor: '#1e40af',
                        transform: 'translateY(-2px)',
                        boxShadow: '0 4px 12px rgba(30, 64, 175, 0.1)'
                      }
                    }}
                    onClick={() => {
                      navigate(action.link);
                    }}
                  >
                    <CardContent sx={{ p: 2.5, flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
                      <Avatar
                        sx={{
                          backgroundColor: '#f8fafc',
                          width: 48,
                          height: 48,
                          mb: 2
                        }}
                      >
                        <Icon size={24} color="#6b7280" />
                      </Avatar>
                      <Typography
                        variant="body2"
                        sx={{
                          fontWeight: '600',
                          color: '#374151',
                          fontSize: '14px',
                          textAlign: 'center'
                        }}
                      >
                        {action.title}
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>
        </Box>
      </Paper>

      {/* Recent Activity */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: '16px',
          border: '1px solid #f0f0f0',
          boxShadow: '0 4px 20px rgba(0,0,0,0.08)'
        }}
      >
        <Box sx={{ p: 3 }}>
          <Typography
            variant="h6"
            sx={{
              fontWeight: 'bold',
              color: '#1f2937',
              mb: 3,
              fontSize: '18px'
            }}
          >
            Recent Activity
          </Typography>
          <List sx={{ p: 0 }}>
            <ListItem sx={{ py: 3, justifyContent: 'center' }}>
              <ListItemText
                primary="No recent activities"
                secondary="Activity will appear here as you use the system"
                primaryTypographyProps={{
                  fontSize: '14px',
                  fontWeight: '500',
                  color: '#6b7280',
                  textAlign: 'center'
                }}
                secondaryTypographyProps={{
                  fontSize: '12px',
                  color: '#9ca3af',
                  textAlign: 'center'
                }}
              />
            </ListItem>
          </List>
        </Box>
      </Paper>
    </Container>
  );
};

export default Dashboard;